package energy;/** * EU电压等级枚举 * <p> * 定义了完整的工业电压系列，从超低压(ULV)到无限制(MAX)。 * 每个等级包含电压名称、最大传输功率(tick)和对应的线缆颜色。 * </p> */public enum EUVoltage {    /** 超低压 - 8 EU/t */    ULV(0, "ULV", 8, 0x7F7F7F),    /** 低压 - 32 EU/t */    LV(1, "LV", 32, 0xFFFFFF),    /** 中压 - 128 EU/t */    MV(2, "MV", 128, 0xDF0000),    /** 高压 - 512 EU/t */    HV(3, "HV", 512, 0xFFFF00),    /** 超高压 - 2048 EU/t */    EV(4, "EV", 2048, 0x808080),    /** 极高电压 - 8192 EU/t */    IV(5, "IV", 8192, 0xD2D2D2),    /** 极限电压 - 32768 EU/t */    LuV(6, "LuV", 32768, 0xD254FF),    /** 零点模块电压 - 131072 EU/t */    ZPM(7, "ZPM", 131072, 0x5454FF),    /** 超电压 - 524288 EU/t */    UV(8, "UV", 524288, 0xFF54FF),    /** 超高压 - 2097152 EU/t */    UHV(9, "UHV", 2097152, 0x000000),    /** 超超电压 - 8388608 EU/t */    UEV(10, "UEV", 8388608, 0x3C3C3C),    /** 超极高电压 - 33554432 EU/t */    UIV(11, "UIV", 33554432, 0xF0F0F0),    /** 超极限电压 - 134217728 EU/t */    UMV(12, "UMV", 134217728, 0xA0A0A0),    /** 超超模块电压 - 536870912 EU/t */    UXV(13, "UXV", 536870912, 0xC8C8C8),    /** 操作电压 - 2147483648 EU/t */    OpV(14, "OpV", 2147483648L, 0xF4F4F4),    /** 无限制 */    MAX(15, "MAX", Long.MAX_VALUE, 0xFFFFFF);    /** 电压等级索引 */    private final int index;    /** 电压名称 */    private final String name;    /** 最大传输功率 (EU/tick) */    private final long maxVoltage;    /** 线缆颜色 (RGB) */    private final int cableColor;    /**     * 构造电压等级     *     * @param index      等级索引     * @param name       等级名称     * @param maxVoltage 最大电压值     * @param cableColor 线缆颜色     */    EUVoltage(int index, String name, long maxVoltage, int cableColor) {        this.index = index;        this.name = name;        this.maxVoltage = maxVoltage;        this.cableColor = cableColor;    }    /**     * 获取电压等级索引     *     * @return 索引值     */    public int getIndex() {        return index;    }    /**     * 获取电压等级名称     *     * @return 名称字符串     */    public String getName() {        return name;    }    /**     * 获取最大传输电压     *     * @return 最大电压值 (EU/t)     */    public long getMaxVoltage() {        return maxVoltage;    }    /**     * 获取线缆颜色     *     * @return RGB颜色值     */    public int getCableColor() {        return cableColor;    }    /**     * 检查给定电压是否在当前等级范围内     *     * @param voltage 要检查的电压     * @return 如果电压在范围内返回true     */    public boolean isVoltageInRange(long voltage) {        return voltage > 0 && voltage <= maxVoltage;    }    /**     * 检查当前等级是否高于指定等级     *     * @param other 另一个电压等级     * @return 如果当前等级更高返回true     */    public boolean isHigherThan(EUVoltage other) {        return this.index > other.index;    }    /**     * 检查当前等级是否低于指定等级     *     * @param other 另一个电压等级     * @return 如果当前等级更低返回true     */    public boolean isLowerThan(EUVoltage other) {        return this.index < other.index;    }    /**     * 获取指定索引对应的电压等级     *     * @param index 等级索引     * @return 对应的电压等级，如果索引无效返回ULV     */    public static EUVoltage fromIndex(int index) {        EUVoltage[] values = values();        if (index >= 0 && index < values.length) {            return values[index];        }        return ULV;    }    /**     * 获取能容纳指定电压的最低等级     *     * @param voltage 电压值     * @return 能容纳该电压的最低等级，如果超出所有等级返回MAX     */    public static EUVoltage getMinVoltageFor(long voltage) {        for (EUVoltage v : values()) {            if (v.maxVoltage >= voltage) {                return v;            }        }        return MAX;    }    /**     * 获取上一级电压等级     *     * @return 上一级等级，如果已是最高返回MAX     */    public EUVoltage getHigher() {        return fromIndex(this.index + 1);    }    /**     * 获取下一级电压等级     *     * @return 下一级等级，如果已是最低返回ULV     */    public EUVoltage getLower() {        return fromIndex(this.index - 1);    }    @Override    public String toString() {        return name + " (" + maxVoltage + " EU/t)";    }}